/**
 * Goal word lists.
 *
 * The lists are plain JSON under `/wordlists`, generated by
 * `tools/build-wordlists.py` from ECDICT (MIT). They hold only what reading
 * rarely teaches: the CET-4 band and everyday high-frequency vocabulary are
 * already removed, and expressions that only appear in speech are kept apart
 * in the hand-written `idioms` list.
 */

export interface WordEntry {
  /** The word or expression. */
  w: string;
  /** Reading: IPA, kana, or pinyin, depending on the list's language. */
  p?: string;
  /** Short gloss. Exam lists in Japanese and Chinese have none. */
  z?: string;
  /** Rarity band: 0 少见, 1 较难, 2 罕见. */
  b: number;
  /** The band's label, written by the generator. */
  bl: string;
}

export interface WordGoal {
  slug: string;
  label: string;
  /** Language of the list: `en`, `ja` or `zh`. */
  lang: string;
  description: string;
  count: number;
  bytes: number;
  source?: string;
  license?: string;
}

export interface WordListIndex {
  sources: { name: string; url: string; license: string }[];
  excluded: { label: string };
  goals: WordGoal[];
}

export interface WordList {
  goal: string;
  label: string;
  lang: string;
  description: string;
  source?: string;
  sourceUrl?: string;
  license?: string;
  count: number;
  words: WordEntry[];
}

/** Language groups in the order the desk shows them. */
export const languageGroups: { id: string; zh: string }[] = [
  { id: 'en', zh: '英语' },
  { id: 'ja', zh: '日语' },
  { id: 'zh', zh: '中文' },
];

/** Group the index by list language, keeping the display order. */
export function goalsByLanguage(goals: WordGoal[]): { id: string; zh: string; goals: WordGoal[] }[] {
  return languageGroups
    .map(group => ({ ...group, goals: goals.filter(goal => goal.lang === group.id) }))
    .filter(group => group.goals.length > 0);
}

const lists = new Map<string, Promise<WordList>>();
let index: Promise<WordListIndex> | null = null;

async function getJson<T>(path: string): Promise<T> {
  const response = await fetch(path, { cache: 'force-cache' });
  if (!response.ok) throw new Error('词单读取失败，请检查本地文件后重试。');
  return response.json() as Promise<T>;
}

/** The goal tabs, in display order, fetched once per session. */
export function loadIndex(): Promise<WordListIndex> {
  index ??= getJson<WordListIndex>('/wordlists/index.json').catch(error => {
    index = null;
    throw error;
  });
  return index;
}

/** One goal's words, fetched once and kept for this session. */
export function loadWords(slug: string): Promise<WordList> {
  let pending = lists.get(slug);
  if (!pending) {
    pending = getJson<WordList>(`/wordlists/${slug}.json`).catch(error => {
      lists.delete(slug);
      throw error;
    });
    lists.set(slug, pending);
  }
  return pending;
}

/** Filter state of the word desk. */
export interface WordFilter {
  query: string;
  band: number | null;
  fresh: boolean;
}

export const emptyFilter: WordFilter = { query: '', band: null, fresh: false };

/**
 * Match a word against the filter. An English query matches the spelling, a
 * Chinese one matches the gloss, so "病" finds words about illness.
 */
export function matchesFilter(entry: WordEntry, filter: WordFilter, analyzed: (word: string) => boolean): boolean {
  if (filter.band !== null && entry.b !== filter.band) return false;
  if (filter.fresh && analyzed(entry.w)) return false;
  const query = filter.query.trim().toLowerCase();
  if (!query) return true;
  return entry.w.toLowerCase().includes(query)
    || (entry.z ?? '').toLowerCase().includes(query)
    || (entry.p ?? '').toLowerCase().includes(query);
}

/** Progress of one goal, counted from the analysed targets. */
export function goalProgress(words: WordEntry[], analyzed: (word: string) => boolean): { done: number; total: number; ratio: number } {
  let done = 0;
  for (const entry of words) if (analyzed(entry.w)) done += 1;
  return { done, total: words.length, ratio: words.length ? done / words.length : 0 };
}

/** A stable key for matching a word against saved analyses. */
export function wordKey(word: string): string {
  return word.trim().toLowerCase();
}
